import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger, type Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

const weatherDefinition = {
  name: 'get_weather',
  description: 'Get weather for a location',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  },
};

const lookupDefinition = {
  name: 'lookup_record',
  description: 'Look up a record',
  inputSchema: {
    type: 'object',
    properties: {identifier: {type: 'string'}},
  },
};

async function captureToolWarnings(
  action: () => Promise<void>
): Promise<Array<{message: string; fields?: Record<string, unknown>}>> {
  const warnings: Array<{message: string; fields?: Record<string, unknown>}> = [];
  const logger: Logger = {
    debug: () => undefined,
    info: () => undefined,
    warn: (category, message, fields) => {
      if (category === 'tool') warnings.push({message, fields});
    },
    error: () => undefined,
  };
  setLogger(logger);
  try {
    await action();
  } finally {
    setLogger();
  }
  return warnings;
}

describe('ToolRegistry input validation', () => {
  it('passes valid input and unlisted properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', extra: 'keep me'};
    let received: Record<string, unknown> | undefined;
    registry.register(
      {
        ...weatherDefinition,
      },
      async value => {
        received = value;
        return 'sunny';
      }
    );

    await registry.execute('get_weather', input);

    expect(received).toEqual(input);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const calls = {count: 0};
    registry.register(
      {
        ...weatherDefinition,
      },
      async () => {
        calls.count += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls: calls.count,
      result: response.result,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      result: expect.any(String),
      mentionsRequiredField: true,
    });
  });

  it('logs the missing required property path and constraint', async () => {
    const warnings = await captureToolWarnings(async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          ...weatherDefinition,
        },
        async () => 'sunny'
      );

      await registry.execute('get_weather', {});
    });

    expect(warnings).toContainEqual({
      message: 'input validation failed',
      fields: {name: 'get_weather', paths: ['/location'], constraints: ['required']},
    });
  });

  it('rejects a wrong-typed property with its path and expected type without leaking the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        ...lookupDefinition,
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      executorCalls,
      result: response.result,
      namesField: response.result.includes('identifier'),
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({
      executorCalls: 0,
      result: expect.any(String),
      namesField: true,
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(weatherDefinition, async () => 'sunny');

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('logs the failing property path without the rejected value', async () => {
    const registry = new ToolRegistry();
    const warnings = await captureToolWarnings(async () => {
      registry.register(
        {
          ...lookupDefinition,
        },
        async () => 'found'
      );

      await registry.execute('lookup_record', {identifier: 123456789});
    });

    expect(warnings).toEqual([
      {
        message: 'input validation failed',
        fields: {name: 'lookup_record', paths: ['/identifier'], constraints: ['type']},
      },
    ]);
  });

  it('rejects an uncompilable static schema at registration and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Broken weather tool',
          inputSchema: {type: 'not-a-json-schema-type'},
        },
        async () => 'sunny'
      )
    ).toThrow("Invalid inputSchema for tool 'broken_weather'");
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => {
        definitionCalls += 1;
        const property = definitionCalls === 2 ? 'location' : 'city';
        return {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {
            type: 'object',
            properties: {[property]: {type: 'string'}},
            required: [property],
          },
        };
      },
      async input => {
        inputs.push(input);
        return 'sunny';
      }
    );

    const first = await registry.execute('get_weather', {location: 'Berlin'});
    const second = await registry.execute('get_weather', {city: 'Paris'});

    expect({
      firstResult: first.result,
      secondResult: second.result,
      inputs,
    }).toEqual({
      firstResult: 'sunny',
      secondResult: 'sunny',
      inputs: [{location: 'Berlin'}, {city: 'Paris'}],
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.test.ts#L45), [acceptance](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property with its path and expected type without leaking the value](../../src/orchestration/tools/registry.test.ts#L102), [validated by: logs the failing property path without the rejected value](../../src/orchestration/tools/registry.test.ts#L145), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- An input that satisfies its schema keeps undeclared properties when it reaches the executor ([validated by: passes valid input and unlisted properties through unchanged](../../src/orchestration/tools/registry.test.ts#L26)).
- Validation log records name the failing property path and constraint, including the missing property for a `required` failure ([validated by: logs the missing required property path and constraint](../../src/orchestration/tools/registry.test.ts#L71)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L132)).
- An invalid static schema is rejected synchronously at registration, and the error names the tool being registered ([validated by: rejects an uncompilable static schema at registration and names the tool](../../src/orchestration/tools/registry.test.ts#L178)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L193)).

## Orchestrator tool-loop recovery

- A tool call causes another provider round, and streamed chunks from both rounds remain in order ([validated by: runs another round after a tool call and streams both rounds in order](../../src/orchestration/chatOrchestrator.test.ts#L455)).
- A response that requests no tool stops after one provider round ([validated by: stops after one round when nothing asked for a tool](../../src/orchestration/chatOrchestrator.test.ts#L467)).
- A tool result rewrites an upserted entry's index to the session index ([validated by: appends an upserted entry to the session and rewrites its index to match](../../src/orchestration/chatOrchestrator.test.ts#L503)).
- A tool result that marks the assistant response handled emits suppression ([validated by: asks for suppression when the tool says the reply is already handled](../../src/orchestration/chatOrchestrator.test.ts#L520)).
- Text from each provider round is joined before the post-response hook runs ([validated by: joins the text of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L532)).
- Usage reported by an earlier provider round is retained when a later round reports none ([validated by: keeps the usage an earlier round reported when a later round reports none](../../src/orchestration/chatOrchestrator.test.ts#L554)).

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a rejected tool call to the provider so it can retry with corrected input](../../src/orchestration/chatOrchestrator.test.ts#L401), [acceptance](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
{
  "scripts": {
    "dev": "tsx watch example/server.ts",
    "build": "node --input-type=module -e \"import {rmSync} from 'node:fs'; rmSync('dist',{recursive:true,force:true})\" && tsc -p tsconfig.build.json",
    "prepare": "npm run build",
    "start": "node dist/index.js",
    "test": "node --experimental-vm-modules node_modules/jest/bin/jest.js",
    "test:coverage": "node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage",
    "smoke": "bash scripts/smoke.sh",
    "typecheck": "tsc --noEmit",
    "typecheck:example": "tsc -p tsconfig.example.json",
    "eslint": "eslint --max-warnings 0 .",
    "lint:backlog": "eslint -c eslint.config.backlog.mjs .",
    "check:spec-links": "node scripts/check-spec-links.mjs",
    "spec:names": "node scripts/check-spec-anchor-names.mjs",
    "spec:names:fix": "node scripts/check-spec-anchor-names.mjs --fix",
    "check:spec-status": "node scripts/check-spec-status.mjs",
    "check:audit": "node scripts/check-audit.mjs",
    "check:action-pins": "node scripts/check-action-pins.mjs",
    "check:version": "bash scripts/check-version.sh",
    "docs:check": "node scripts/check-doc-blocks.mjs",
    "docs:check-paths": "node scripts/check-doc-paths.mjs",
    "docs:check-spikes": "node scripts/check-spike-status.mjs",
    "check:regions": "node scripts/check-doc-regions.mjs",
    "docs:fix": "node scripts/check-doc-blocks.mjs --fix",
    "verify": "npm run typecheck && npm run typecheck:example && npm run eslint && npm run lint:backlog && npm run prettier:check && npm run test:coverage && npm run build && npm run docs:check && npm run docs:check-paths && npm run docs:check-spikes && npm run check:regions && npm run spec:names && npm run check:spec-links && npm run check:spec-status",
    "lint": "npm run eslint",
    "check:build-chain": "npm run check:audit && npm run check:action-pins",
    "prettier": "prettier --write \"{src,scripts,smoke}/**/*.ts\"",
    "prettier:check": "prettier --check \"{src,scripts,smoke}/**/*.ts\""
  },
  "version": "0.3.0"
}

